class IntroductionDictionary extends StatelessWidget {
  const IntroductionDictionary({super.key});
 Future<void> share() async {
    await FlutterShare.share(
      title: "مقدمة",
      text:"المقدمة: بِسْمِ اللهِ الرَّحْمَنِ الرَّحيمِ قال الشيخُ الإِمامُ الأجلُّ الأوحدُ العالم. أبو منصورٍ موهوبُ بنُ أحمدَ بن مـحمد بن الخَضِرِ [الجوالِيقي] أطال اللهُ بقاءَه، وحَرَس مُدَّته وحَوْبَاءَهُ: هذا كتابٌ نذكرُ فيه ما تكلمتْ به العرب من الكلام الأعجميِّ، ونطق به القرآنُ الـمَـجِيد، ووردَ في أخبار الرسولِ صلى الله عليه وسلم والصحابة والتابعين، رضوانُ الله عليهم [أجمعين]، وذَكَرتْهُ العربُ في أشعارها وأخبارِها؛ ليُعْرَفَ الدخيل من الصَّرِيح. ففي معرفة ذلك فائدةٌ جليلةٌ، وهي أن يحترِس المشْتَقُّ فلا يجعلَ شيئًا من لغة العرب لشيءٍ من لغة العجمِ. فقد قال [أبوبكر] بنُ السَرَّاجِ في رسالته في الاشتقاق، في (باب ما يَجبُ على الناظر في الاشتقاق أن يَتَوقَّاهُ ويحترسَ منه): «مِمّا ينبغي أن يَحْذَرَ منه كلَّ الحَذَرِ أن يَشْتَقَّ من لغة العرب لشيءٍ من لغة العجمِ، فيكونَ بمنزلة من ادَّعَى أن الطيرَ وَلَدُ الحُوتِ». [وحُكِيَ عن أبي عليٍّ قال: رأيتُ أبا بكرٍ يُدِيرُ هذه اللفظةَ «بُوصِيٌّ» ليَشْتَقَّها، فقلتُ: أين تذهبُ، إنّها فارسيةٌ، إنما هو «بُوزيد» وهو اسمُ جَدِّنَا! قال: ومعناهُ: السَّالمُ. فقال أبوبكرٍ: فَرَّجْتَ عَنِّي]. فأمّا ما ورد منه في القرآن، فقد اختلفَ فيه أهلُ العلم: [فـ]ــقال بعضهم: كتابُ الله [تعالی] ليس فيه شيءٌ من غَير العربيَّةِ. أخبرنِي غيرُ واحدٍ عن الحسن بن أحمدَ عن دَعْلَجٍ عن علي بن عبد العزيز عن أبي عُبَيْدٍ قال: سمعت أبا عُبَيْدة يقول: من زعم أن في القرآن لسانًا سوى العربية فقد أَعْظَمَ عَلى اللهِ القولَ. واحتج بقوله تعالى: ﴿إِنَّا جَعَلْنَاهُ قُرْآنًا عَرَبِيًّا﴾، سورة الزخرف (3). قال أبو عبيدٍ: ورُوي عن ابن عباسٍ ومجاهدٍ وعكْرِمَةَ وغيرهِم، في أحرفٍ كثيرة: أنه من غير لسان العرب، مثلُ «سجِّيل» و«المِشْکاةِ» و«اليَمِّ» و«الطُّورِ» و«أَبَارِيقَ» و«إسْتَبْرقٍ» وغيرِ ذلك. فهؤلاء أعلم بالتأويل من أبي عُبيدةَ. ولكنهم ذَهبوا إلى مذهبٍ، وذهب هذا إلى غيره. وكلاهما مصيبٌ إن شاء الله تعالی. وذلك: أن هذه الحروف بغير لسان العرب في الأصلِ، فقال أولئك على الأصل، ثم لفظتْ به العرب بألسنتها، فعرَّبَتْه، فصار عربيًّا بتعريبها إيَّاه، فهي عربيةٌ في هذه الحال، أعجميةُ الأصلِ. فهذا القولُ يُصَدِّقُ الفريقين جميعًا. والأسماءُ المعَرَّبةُ [في الصَّرْفِ وتركِه] على ضربين: أحدُهما لا يُعْتَدُّ بعُجْمَتِه، وهو ما أُدخل عليه لام التَّعريفِ، نحو «الدِّيباج» و«الدِّيوان». والثاني: ما يُعْتَدُّ بعجمته. وهو ما لم يُدْخلُوا عليه لامَ التعريفِ كـ«ـموسی» و«عيسی».المصدر: الجواليقي، المعرّب من الكلام الأعجمي على حروف المعجم، تح: أحمد محمد شاكر، مطبعة دار الكتب والوثائق القومية، القاهرة، مصر، ط5، 2020م، ص:3/4/5.",
    );
  }
